const bannedPhrases = ["i'd love to","i would love the opportunity","excited","thrilled","passionate","delve","seamless","seamlessly","elevate","leverage","robust","streamline","cutting-edge","top-notch","resonates","aligns perfectly","i understand you're looking for","in today's competitive market","rest assured","look no further","furthermore","moreover"];
const text = (typeof query === 'string') ? query : String(query || '');
const lower = text.toLowerCase();
const violations = [];
if (/[—–]/.test(text)) {
  violations.push('Contains an em dash or en dash character.');
}
for (const phrase of bannedPhrases) {
  if (lower.includes(phrase)) {
    violations.push('Contains banned phrase: "' + phrase + '"');
  }
}
if (violations.length === 0) {
  return 'PASS: no banned phrases or dashes found.';
}
return 'FAIL:\n' + violations.join('\n');
